  "push.ask.notNow": "ਹੁਣੇ ਨਹੀਂ",
  "push.status.on": "ਇਸ ਫੋਨ 'ਤੇ ਨੋਟੀਫਿਕੇਸ਼ਨ ਚਾਲੂ ਹਨ।",
  "push.status.off": "ਇਸ ਫੋਨ 'ਤੇ ਨੋਟੀਫਿਕੇਸ਼ਨ ਬੰਦ ਹਨ। ਨਵੇਂ ਨੋਟੀਫਿਕੇਸ਼ਨ ਤੁਹਾਨੂੰ ਐਪ ਖੋਲ੍ਹਣ 'ਤੇ ਹੀ ਦਿਖਣਗੇ।",
  "push.status.blocked": "ਇਸ ਫੋਨ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ECCS ਦੇ ਨੋਟੀਫਿਕੇਸ਼ਨ ਬਲੌਕ ਹਨ। ਤੁਰੰਤ ਪਤਾ ਲੱਗਣ ਲਈ ਉੱਥੇ ਇਨ੍ਹਾਂ ਨੂੰ ਇਜਾਜ਼ਤ ਦਿਓ।",
