  "public.how.heading": "ਇਹ ਕਿਵੇਂ ਕੱਢਿਆ ਜਾਂਦਾ ਹੈ",
  "public.how.1": "ECCS ਦਾ ਇੰਸਪੈਕਟਰ ਕਿਚਨ ਵਿੱਚ ਆ ਕੇ ਇੱਕ-ਇੱਕ ਨੁਕਤਾ ਚੈੱਕ ਕਰਦਾ ਹੈ: ਸਟਾਫ ਦੀ ਹਾਈਜੀਨ, ਖਾਣਾ ਰੱਖਣਾ, ਪਕਾਉਣਾ, ਸਫ਼ਾਈ, ਪੈਸਟ ਕੰਟਰੋਲ, ਪਾਣੀ, ਕੂੜਾ ਅਤੇ ਸਾਮਾਨ।",
  "public.how.2": "ਹਰ ਨੁਕਤੇ ਬਾਰੇ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ ਕਿ ਉਹ ਪੂਰਾ ਹੋਇਆ ਜਾਂ ਨਹੀਂ। ਜਿੰਨੇ ਨੰਬਰ ਮਿਲ ਸਕਦੇ ਸਨ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਜਿੰਨੇ ਮਿਲੇ, ਉਹੀ 100 ਵਿੱਚੋਂ ਇੱਕ ਅੰਕ ਵਜੋਂ ਸਕੋਰ ਹੈ। ਗੰਭੀਰ ਖ਼ਤਰੇ ਵਾਲੇ ਨੁਕਤਿਆਂ ਦੇ ਨੰਬਰ ਦੁੱਗਣੇ ਗਿਣੇ ਜਾਂਦੇ ਹਨ।",
  "public.how.3": "ਗ੍ਰੇਡ A+ ਦਾ ਮਤਲਬ {aPlus} ਜਾਂ ਵੱਧ, A ਦਾ ਮਤਲਬ {a} ਜਾਂ ਵੱਧ, B ਦਾ ਮਤਲਬ {b} ਜਾਂ ਵੱਧ। {b} ਤੋਂ ਘੱਟ ਹੋਵੇ, ਜਾਂ ਗੰਭੀਰ ਖ਼ਤਰੇ ਵਾਲਾ ਕੋਈ ਨੁਕਤਾ ਪੂਰਾ ਨਾ ਹੋਇਆ ਹੋਵੇ, ਤਾਂ ਕੋਈ ਗ੍ਰੇਡ ਨਹੀਂ ਦਿੱਤਾ ਜਾਂਦਾ।",
  "public.how.4": "ਹਰ ਰਿਪੋਰਟ ਇੱਥੇ ਦਿਖਣ ਤੋਂ ਪਹਿਲਾਂ ECCS ਦਾ ਦਫ਼ਤਰ ਉਸਨੂੰ ਮਨਜ਼ੂਰ ਕਰਦਾ ਹੈ। ਨਤੀਜਾ {days} ਦਿਨ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਫਿਰ ਅਗਲੀ ਇੰਸਪੈਕਸ਼ਨ ਤੱਕ ਇਸ ਪੇਜ ਤੋਂ ਹਟਾ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।",
  "public.not.heading": "ਇਸ ਵਿੱਚ ਕੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ",
  "public.not.1": "ਇਹ ਉਹ ਦਿਖਾਉਂਦਾ ਹੈ ਜੋ ECCS ਨੂੰ ਇੰਸਪੈਕਸ਼ਨ ਵਾਲੇ ਦਿਨ ਮਿਲਿਆ। ਅੱਜ ਕਿਚਨ ਕਿਹੋ ਜਿਹੀ ਹੈ, ਇਸਦੀ ਗਾਰੰਟੀ ਇਹ ਨਹੀਂ ਦੇ ਸਕਦਾ।",
  "public.not.2": "ਖਾਣੇ ਦੇ ਸੁਆਦ ਜਾਂ ਕੁਆਲਿਟੀ, ਸਰਵਿਸ ਜਾਂ ਬੈਠ ਕੇ ਖਾਣ ਵਾਲੀ ਥਾਂ ਬਾਰੇ ਇਹ ਕੁਝ ਨਹੀਂ ਦੱਸਦਾ।",
  "public.not.3": "ਇਹ ਕੋਈ ਗਾਰੰਟੀ ਨਹੀਂ ਕਿ ਖਾਣਾ ਤੁਹਾਡੇ ਲਈ ਸੁਰੱਖਿਅਤ ਹੈ। ਜੇ ਤੁਹਾਨੂੰ ਕੋਈ ਐਲਰਜੀ ਹੈ ਤਾਂ ਸਟਾਫ ਨੂੰ ਪੁੱਛੋ।",
  "public.not.4": "ਰੈਸਟੋਰੈਂਟ ਕਲੀਨਿੰਗ ਅਤੇ ਹਾਈਜੀਨ ਸਰਵਿਸਾਂ ਲਈ ECCS ਨੂੰ ਪੈਸੇ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਇਹ ਪੇਜ ਦਿਖਾਉਣਾ ਹੈ ਜਾਂ ਨਹੀਂ, ਇਹ ਰੈਸਟੋਰੈਂਟ ਆਪ ਤੈਅ ਕਰਦਾ ਹੈ।",
  "public.gov.heading": "ਸਰਕਾਰੀ ਰੇਟਿੰਗ ਨਹੀਂ",
  "public.gov.body": "ਇਹ ਪੇਜ ECCS ਦਾ ਹੈ, ਜੋ ਇੱਕ ਪ੍ਰਾਈਵੇਟ ਕੰਪਨੀ ਹੈ। ਇਹ FSSAI ਜਾਂ ਕਿਸੇ ਸਰਕਾਰੀ ਅਦਾਰੇ ਵੱਲੋਂ ਜਾਰੀ ਜਾਂ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕੀਤਾ ਗਿਆ, ਅਤੇ ਇਹ FSSAI ਹਾਈਜੀਨ ਰੇਟਿੰਗ ਨਹੀਂ ਹੈ।",
  "public.gov.licence": "ਇਸ ਆਊਟਲੈੱਟ ਲਈ ਦਰਜ FSSAI ਲਾਇਸੈਂਸ ਨੰਬਰ: {number}",
  "public.gov.check": "ਹਰ ਰੈਸਟੋਰੈਂਟ ਲਈ ਆਪਣਾ FSSAI ਲਾਇਸੈਂਸ ਸਭ ਨੂੰ ਦਿਖਦੀ ਥਾਂ 'ਤੇ ਲਗਾਉਣਾ ਜ਼ਰੂਰੀ ਹੈ। ਤੁਸੀਂ FSSAI ਦੀ ਆਪਣੀ ਵੈੱਬਸਾਈਟ (foscos.fssai.gov.in) 'ਤੇ ਜਾਂ ਉਸਦੀ Food Safety Connect ਐਪ ਵਿੱਚ ਲਾਇਸੈਂਸ ਚੈੱਕ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਸ਼ਿਕਾਇਤ ਕਰ ਸਕਦੇ ਹੋ।",
  "public.updated": "ਪੇਜ ਆਖਰੀ ਵਾਰ ਅੱਪਡੇਟ ਹੋਇਆ: {date}, {time}।",
  "public.footer": "ECCS · Eosfera Commercial Cleaning Services, ਹੈਦਰਾਬਾਦ",
