  "public.none.body": "ਇਸ ਲਿੰਕ 'ਤੇ ਇਸ ਵੇਲੇ ਕੋਈ ਚਾਲੂ ECCS ਹਾਈਜੀਨ ਨਤੀਜਾ ਨਹੀਂ ਹੈ। ਹੋ ਸਕਦਾ ਹੈ ਲਿੰਕ ਪੁਰਾਣਾ ਹੋਵੇ, ਜਾਂ ਪੇਜ ਇਸ ਵੇਲੇ ਦਿਖਾਇਆ ਨਾ ਜਾ ਰਿਹਾ ਹੋਵੇ।",
  "public.none.gov": "ਕਿਸੇ ਰੈਸਟੋਰੈਂਟ ਦਾ FSSAI ਲਾਇਸੈਂਸ ਚੈੱਕ ਕਰਨ ਲਈ FSSAI ਦੀ ਆਪਣੀ ਵੈੱਬਸਾਈਟ (foscos.fssai.gov.in) ਜਾਂ ਉਸਦੀ Food Safety Connect ਐਪ ਵਰਤੋ।",
  "public.down": "ਇਹ ਪੇਜ ਇਸ ਵੇਲੇ ਖੁੱਲ੍ਹ ਨਹੀਂ ਰਿਹਾ। ਇੱਕ ਮਿੰਟ ਬਾਅਦ ਫਿਰ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
