  "face.declinedHelp": "ਇਹ ਸਹਿਮਤ ਨਹੀਂ ਹੋਏ, ਅਤੇ ਇਸ ਵਿੱਚ ਕੋਈ ਹਰਜ ਨਹੀਂ। ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਆਪਣੇ PIN ਨਾਲ ਇਸ ਬੰਦੇ ਦਾ ਕਲਾਕ ਇਨ ਅਤੇ ਕਲਾਕ ਆਊਟ ਕਰਦੇ ਹਨ। ਇਨ੍ਹਾਂ ਲਈ ਹੋਰ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ।",
  "face.leftHelp": "ਇਹ ਬੰਦਾ ਕੰਮ ਛੱਡ ਗਿਆ ਹੈ। ਇਨ੍ਹਾਂ ਦੇ ਚਿਹਰੇ ਦਾ ਪੈਟਰਨ ਮਿਟਾ ਦਿੱਤਾ ਗਿਆ ਹੈ।",
  "face.ownerOnly": "ਸਿਰਫ਼ ਮਾਲਕ ਹੀ ਚਿਹਰਾ ਜੋੜ ਜਾਂ ਹਟਾ ਸਕਦਾ ਹੈ।",
  "face.start": "ਇਨ੍ਹਾਂ ਦਾ ਚਿਹਰਾ ਜੋੜੋ",
  "face.again": "ਇਨ੍ਹਾਂ ਦਾ ਚਿਹਰਾ ਦੁਬਾਰਾ ਲਓ",
  "face.startHint": "ਪਹਿਲਾਂ ਫੋਨ {name} ਨੂੰ ਫੜਾਓ, ਤਾਂ ਜੋ ਉਹ ਪੜ੍ਹ ਕੇ ਸਹਿਮਤ ਹੋ ਸਕਣ",
  "face.remove": "ਚਿਹਰਾ ਹਟਾਓ",
  "face.removeConfirm": "{name} ਦਾ ਚਿਹਰਾ ਹਟਾਉਣਾ ਹੈ? ਉਨ੍ਹਾਂ ਦੇ ਚਿਹਰੇ ਦਾ ਪੈਟਰਨ ਤੁਰੰਤ ਮਿਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ। ਫਿਰ ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਉਨ੍ਹਾਂ ਦਾ ਕਲਾਕ ਇਨ ਅਤੇ ਕਲਾਕ ਆਊਟ ਕਰਨਗੇ।",
